/* pn_ss_test_terms.h: the spin-spin energy of a compact binary and the S^2 coefficients of its
 * circular-orbit energy, for tests/unit/test_pn_ss.c, generated by machine (sympy, from the LaTeX
 * source of A. Bohe, G. Faye, S. Marsat, E. K. Porter, CQG 32, 195010 (2015), arXiv:1501.01529,
 * Sec. 3.4, by a script kept outside the repository) like the coefficient blocks of
 * src/rel/pn_higher.c, in units G m = c = 1, S = S1 + S2, Sigma = S2 / X2 - S1 / X1,
 * kp = kappa1 + kappa2, km = kappa1 - kappa2, dm = X1 - X2. */
#ifndef MYB_TESTS_PN_SS_TEST_TERMS_H_
#define MYB_TESTS_PN_SS_TEST_TERMS_H_

/* E_SS / mu at 1/c^4 (e_4^0 / 4, over r^3) */
static double pn_ss_energy4(double nu, double dm, double kp, double km, double ri,
                             double rd, double v2, double ns, double nz, double vs,
                             double vz, double ss, double zz, double sz) {
  const double ns2 = ns * ns, nz2 = nz * nz, vs2 = vs * vs, vz2 = vz * vz;
  const double nu2 = nu * nu, rd2 = rd * rd;
  const double ri2 = ri * ri, ri3 = ri2 * ri, ri4 = ri3 * ri;
  (void)rd; (void)v2; (void)vs; (void)vz; (void)vs2; (void)vz2; (void)nu2; (void)rd2;
  (void)ri4; (void)ns2; (void)nz2;
  double e = 0.0;
  e += sz * (ri3 * (1.0 / 2.0 * km - dm - 1.0 / 2.0 * dm * kp));
  e += zz * (ri3 * (-1.0 / 4.0 * kp + 1.0 / 4.0 * dm * km + nu + 1.0 / 2.0 * nu * kp));
  e += ss * (ri3 * (-1.0 - 1.0 / 2.0 * kp));
  e += nz2 * (ri3 * (3.0 / 4.0 * kp - 3.0 / 4.0 * dm * km - 3.0 * nu - 3.0 / 2.0 * nu * kp));
  e += ns * nz * (ri3 * (-3.0 / 2.0 * km + 3.0 * dm + 3.0 / 2.0 * dm * kp));
  e += ns2 * (ri3 * (3.0 + 3.0 / 2.0 * kp));
  return e;
}

/* E_SS / mu at 1/c^6 (e_6^0 / 8 + e_6^1 / (4 r), over r^3) */
static double pn_ss_energy6(double nu, double dm, double kp, double km, double ri,
                             double rd, double v2, double ns, double nz, double vs,
                             double vz, double ss, double zz, double sz) {
  const double ns2 = ns * ns, nz2 = nz * nz, vs2 = vs * vs, vz2 = vz * vz;
  const double nu2 = nu * nu, rd2 = rd * rd;
  const double ri2 = ri * ri, ri3 = ri2 * ri, ri4 = ri3 * ri;
  (void)rd; (void)v2; (void)vs; (void)vz; (void)vs2; (void)vz2; (void)nu2; (void)rd2;
  (void)ri4; (void)ns2; (void)nz2;
  double e = 0.0;
  e += sz * (ri3 * v2 * (-5.0 / 4.0 * km - 13.0 / 2.0 * dm + 5.0 / 4.0 * dm * kp + 3.0 / 4.0 * nu * km + 1.0 / 2.0 * nu * dm + 1.0 / 4.0 * nu * dm * kp) +
    ri3 * rd2 * (3.0 / 2.0 * km + 6.0 * dm - 3.0 / 2.0 * dm * kp - 15.0 / 4.0 * nu * km + 3.0 / 2.0 * nu * dm + 3.0 / 4.0 * nu * dm * kp) +
    ri4 * (-2.0 * km + 2.0 * dm + 2.0 * dm * kp + 3.0 * nu * km));
  e += zz * (ri3 * v2 * (-3.0 + 5.0 / 8.0 * kp - 5.0 / 8.0 * dm * km + 19.0 / 2.0 * nu - 11.0 / 8.0 * nu * kp + 1.0 / 8.0 * nu * dm * km - 1.0 / 2.0 * nu2 - 1.0 / 4.0 * nu2 * kp) +
    ri3 * rd2 * (3.0 - 3.0 / 4.0 * kp + 3.0 / 4.0 * dm * km - 9.0 * nu + 21.0 / 8.0 * nu * kp - 9.0 / 8.0 * nu * dm * km - 3.0 / 2.0 * nu2 - 3.0 / 4.0 * nu2 * kp) +
    ri4 * (kp - dm * km - 5.0 / 2.0 * nu - 11.0 / 4.0 * nu * kp + 3.0 / 4.0 * nu * dm * km));
  e += ss * (ri3 * v2 * (-7.0 / 2.0 + kp - 1.0 / 4.0 * dm * km + 1.0 / 2.0 * nu + 1.0 / 4.0 * nu * kp) +
    ri3 * rd2 * (3.0 - 3.0 / 4.0 * kp + 3.0 / 4.0 * dm * km + 3.0 / 2.0 * nu + 3.0 / 4.0 * nu * kp) +
    ri4 * (2.0 + 5.0 / 4.0 * kp - 3.0 / 4.0 * dm * km));
  e += vz2 * (ri3 * (3.0 - 3.0 / 4.0 * kp + 3.0 / 4.0 * dm * km - 19.0 / 2.0 * nu + 9.0 / 4.0 * nu * kp - 3.0 / 4.0 * nu * dm * km));
  e += vs * vz * (ri3 * (3.0 / 2.0 * km + 13.0 / 2.0 * dm - 3.0 / 2.0 * dm * kp - 3.0 * nu * km));
  e += vs2 * (ri3 * (7.0 / 2.0 - 3.0 / 4.0 * kp + 3.0 / 4.0 * dm * km));
  e += nz * vz * (ri3 * rd * (-9.0 + 9.0 / 4.0 * kp - 9.0 / 4.0 * dm * km + 57.0 / 2.0 * nu - 6.0 * nu * kp + 3.0 / 2.0 * nu * dm * km - 3.0 * nu2 - 3.0 / 2.0 * nu2 * kp));
  e += nz * vs * (ri3 * rd * (-9.0 / 4.0 * km - 9.0 * dm + 9.0 / 4.0 * dm * kp + 15.0 / 4.0 * nu * km + 3.0 / 2.0 * nu * dm + 3.0 / 4.0 * nu * dm * kp));
  e += nz2 * (ri3 * v2 * (6.0 - 9.0 / 8.0 * kp + 9.0 / 8.0 * dm * km - 39.0 / 2.0 * nu + 15.0 / 8.0 * nu * kp + 3.0 / 8.0 * nu * dm * km + 3.0 / 2.0 * nu2 + 3.0 / 4.0 * nu2 * kp) +
    ri3 * rd2 * (-15.0 / 8.0 * nu * kp + 15.0 / 8.0 * nu * dm * km + 15.0 / 2.0 * nu2 + 15.0 / 4.0 * nu2 * kp) +
    ri4 * (-3.0 * kp + 3.0 * dm * km + 15.0 / 2.0 * nu + 33.0 / 4.0 * nu * kp - 9.0 / 4.0 * nu * dm * km));
  e += ns * vz * (ri3 * rd * (-9.0 / 4.0 * km - 21.0 / 2.0 * dm + 9.0 / 4.0 * dm * kp + 15.0 / 4.0 * nu * km + 3.0 / 2.0 * nu * dm + 3.0 / 4.0 * nu * dm * kp));
  e += ns * vs * (ri3 * rd * (-21.0 / 2.0 + 9.0 / 4.0 * kp - 9.0 / 4.0 * dm * km + 3.0 * nu + 3.0 / 2.0 * nu * kp));
  e += ns * nz * (ri3 * v2 * (9.0 / 4.0 * km + 27.0 / 2.0 * dm - 9.0 / 4.0 * dm * kp + 3.0 / 4.0 * nu * km - 3.0 / 2.0 * nu * dm - 3.0 / 4.0 * nu * dm * kp) +
    ri3 * rd2 * (15.0 / 4.0 * nu * km - 15.0 / 2.0 * nu * dm - 15.0 / 4.0 * nu * dm * kp) +
    ri4 * (6.0 * km - 8.0 * dm - 6.0 * dm * kp - 9.0 * nu * km));
  e += ns2 * (ri3 * v2 * (15.0 / 2.0 - 9.0 / 4.0 * kp - 3.0 / 2.0 * nu - 3.0 / 4.0 * nu * kp) +
    ri3 * rd2 * (-15.0 / 2.0 * nu - 15.0 / 4.0 * nu * kp) +
    ri4 * (-9.0 - 15.0 / 4.0 * kp + 9.0 / 4.0 * dm * km));
  return e;
}

/* the S^2 part of E(x) / (-mu x / 2) at x^2, eq. (Ecirc) (sl = S_l, zl = Sigma_l) */
static double pn_ss_ecirc2(double nu, double dm, double kp, double km, double sl,
                           double zl) {
  const double nu2 = nu * nu, sl2 = sl * sl, zl2 = zl * zl;
  (void)nu2;
  return zl2 * (-1.0 / 2.0 * kp + 1.0 / 2.0 * dm * km + 2.0 * nu + nu * kp) +
    sl * zl * (km - 2.0 * dm - dm * kp) +
    sl2 * (-2.0 - kp);
}

/* the S^2 part of E(x) / (-mu x / 2) at x^3, eq. (Ecirc) (sl = S_l, zl = Sigma_l) */
static double pn_ss_ecirc3(double nu, double dm, double kp, double km, double sl,
                           double zl) {
  const double nu2 = nu * nu, sl2 = sl * sl, zl2 = zl * zl;
  (void)nu2;
  return zl2 * (5.0 - 5.0 / 4.0 * kp + 5.0 / 4.0 * dm * km - 10.0 * nu + 5.0 / 4.0 * nu * kp + 5.0 / 4.0 * nu * dm * km - 5.0 / 3.0 * nu2 - 5.0 / 6.0 * nu2 * kp) +
    sl * zl * (5.0 / 2.0 * km + 25.0 / 3.0 * dm - 5.0 / 2.0 * dm * kp + 35.0 / 6.0 * nu * km + 5.0 / 3.0 * nu * dm + 5.0 / 6.0 * nu * dm * kp) +
    sl2 * (50.0 / 9.0 - 25.0 / 6.0 * kp - 5.0 / 3.0 * dm * km + 5.0 / 3.0 * nu + 5.0 / 6.0 * nu * kp);
}

#endif /* MYB_TESTS_PN_SS_TEST_TERMS_H_ */
